const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d = $input.first().json;

return [
  {
    json: {
      success: d.success === true,
      workflow: $workflow.name,
      model: d.model,
      result: {
        subject: d.subject,
        opener: d.opener,
        valueProposition: d.valueProposition,
        cta: d.cta,
        email: d.email
      },
      generatedAt: d.generatedAt,
      completedAt: new Date().toISOString()
    }
  }
];

values.content:
=You are an elite B2B sales copywriter.

Using the prospect information below, generate a highly personalized cold outreach email.

Prospect Information

First Name: {{$json.prospect.firstName}}

Company: {{$json.prospect.company}}

Role: {{$json.prospect.role}}

Industry: {{$json.prospect.industry}}

Buying Signal: {{$json.prospect.signal}}

Pain Point: {{$json.prospect.painPoint}}

Requirements:

• Write a compelling subject line.
• Write a personalized opening sentence.
• Explain how AI automation and n8n workflows solve their specific problem.
• Keep the email between 125 and 175 words.
• Sound professional, conversational, and natural.
• Never sound overly salesy.
• End with a simple CTA asking for a 15-minute conversation.

Return ONLY valid JSON using this exact structure:

{
  "subject": "",
  "opener": "",
  "valueProposition": "",
  "cta": "",
  "email": ""
}

