{
  "type": "object",
  "properties": {
    "subject": {
      "type": "string",
      "description": "Compelling personalized subject line"
    },
    "opener": {
      "type": "string",
      "description": "Personalized opening sentence"
    },
    "valueProposition": {
      "type": "string",
      "description": "Short value proposition explaining how the solution addresses the prospect's pain point"
    },
    "cta": {
      "type": "string",
      "description": "Simple call to action requesting a 15-minute meeting"
    },
    "email": {
      "type": "string",
      "description": "Complete outreach email"
    }
  },
  "required": [
    "subject",
    "opener",
    "valueProposition",
    "cta",
    "email"
  ],
  "additionalProperties": false
}

