// Extract the structured AI response
const ai = response.output[0].content[0].text;

return [
  {
    json: {
      success: true,
      subject: ai.subject,
      opener: ai.opener,
      valueProposition: ai.valueProposition,
      cta: ai.cta,
      email: ai.email,
      generatedAt: new Date().toISOString(),
      model: "gpt-5-mini"
    }
  }
];
